"""``cell-flow`` 命令行入口。

用法::

    cell-flow analyze --input <表达矩阵.tsv|mtx目录> --output-dir <结果目录> \\
        [--input-format tsv|mtx] \\
        [--min-genes 200] [--max-mito-fraction 0.2] [--min-cells 3] \\
        [--mito-prefix MT-] [--n-hvg 2000] [--n-clusters 2|auto] [--seed 20240617]
"""

import sys
from typing import Optional, Sequence

from . import __version__
from .errors import CellFlowError
from .pca import MAX_PCS
from .pipeline import DEFAULT_SEED, Config, INPUT_FORMATS, run

USAGE = (
    "用法：cell-flow analyze --input <表达矩阵.tsv|mtx目录> --output-dir <结果目录>\n"
    "                [--input-format tsv|mtx]\n"
    "                [--min-genes N] [--max-mito-fraction F] [--min-cells N]\n"
    "                [--mito-prefix PREFIX] [--n-hvg N] [--n-pcs N]\n"
    "                [--n-clusters N|auto] [--seed N]\n"
    "      cell-flow --version"
)


def _fail_usage(message: str) -> "CellFlowError":
    # 延迟导入以避免循环引用
    from .errors import CellFlowConfigError

    return CellFlowConfigError(f"{message}\n{USAGE}")


def _parse_int(name: str, raw: str) -> int:
    try:
        value = int(raw, 10)
    except (TypeError, ValueError):
        raise _fail_usage(f"参数 {name} 需要整数，得到 {raw!r}")
    return value


def _parse_float(name: str, raw: str) -> float:
    try:
        value = float(raw)
    except (TypeError, ValueError):
        raise _fail_usage(f"参数 {name} 需要数值，得到 {raw!r}")
    if value != value or value in (float("inf"), float("-inf")):
        raise _fail_usage(f"参数 {name} 必须是有限数值，得到 {raw!r}")
    return value


def _parse_n_clusters(raw: str):
    # auto（逐字小写）启用自动选择；其余取值仍按整数解析，<2 由 validate_config 拒绝
    if raw == "auto":
        return "auto"
    return _parse_int("--n-clusters", raw)


def _build_analyze_config(options: dict) -> Config:
    if options.get("input") is None:
        raise _fail_usage("缺少必需参数 --input")
    if options.get("output_dir") is None:
        raise _fail_usage("缺少必需参数 --output-dir")
    return Config(
        input_path=options["input"],
        output_dir=options["output_dir"],
        min_genes=_parse_int("--min-genes", options["min_genes"]),
        max_mito_fraction=_parse_float(
            "--max-mito-fraction", options["max_mito_fraction"]
        ),
        min_cells=_parse_int("--min-cells", options["min_cells"]),
        mito_prefix=options["mito_prefix"],
        n_hvg=_parse_int("--n-hvg", options["n_hvg"]),
        n_pcs=_parse_int("--n-pcs", options["n_pcs"]),
        n_clusters=_parse_n_clusters(options["n_clusters"]),
        seed=_parse_int("--seed", options["seed"]),
        input_format=_parse_input_format(options["input_format"]),
    )


def _parse_input_format(raw: str) -> str:
    if raw not in INPUT_FORMATS:
        raise _fail_usage(
            f"--input-format 只能是 tsv 或 mtx，得到 {raw!r}"
        )
    return raw


def _parse_analyze(argv: Sequence[str]) -> Config:
    # argparse 的退出码是 2，与本工具“配置错误退出 3”冲突，故自行做确定解析
    value_options = {
        "--input": "input",
        "--output-dir": "output_dir",
        "--input-format": "input_format",
        "--min-genes": "min_genes",
        "--max-mito-fraction": "max_mito_fraction",
        "--min-cells": "min_cells",
        "--mito-prefix": "mito_prefix",
        "--n-hvg": "n_hvg",
        "--n-pcs": "n_pcs",
        "--n-clusters": "n_clusters",
        "--seed": "seed",
    }
    options = {
        "input_format": "tsv",
        "min_genes": "200",
        "max_mito_fraction": "0.2",
        "min_cells": "3",
        "mito_prefix": "MT-",
        "n_hvg": "2000",
        "n_pcs": str(MAX_PCS),
        "n_clusters": "2",
        "seed": str(DEFAULT_SEED),
    }

    index = 0
    while index < len(argv):
        token = argv[index]
        if token.startswith("--") and "=" in token:
            key, raw_value = token.split("=", 1)
            if key not in value_options:
                raise _fail_usage(f"未知参数 {key}")
            options[value_options[key]] = raw_value
            index += 1
            continue
        if token in value_options:
            if index + 1 >= len(argv):
                raise _fail_usage(f"参数 {token} 缺少取值")
            options[value_options[token]] = argv[index + 1]
            index += 2
            continue
        raise _fail_usage(f"无法识别的参数或多余位置参数：{token}")

    return _build_analyze_config(options)


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]

    if not argv:
        message = _fail_usage("缺少子命令")
        print(f"cell-flow: 错误: {message}", file=sys.stderr)
        return message.exit_code
    if argv[0] in ("-h", "--help"):
        print(USAGE)
        return 0
    if argv[0] in ("-V", "--version"):
        print(f"cell-flow {__version__}")
        return 0
    if argv[0] != "analyze":
        message = _fail_usage(f"未知子命令 {argv[0]!r}")
        print(f"cell-flow: 错误: {message}", file=sys.stderr)
        return message.exit_code

    if any(token in ("-h", "--help") for token in argv[1:]):
        print(USAGE)
        return 0

    try:
        config = _parse_analyze(argv[1:])
        written = run(config)
    except CellFlowError as exc:
        print(f"cell-flow: 错误: {exc}", file=sys.stderr)
        return exc.exit_code

    print(
        f"cell-flow: 分析完成，写出 {len(written)} 个文件至 {config.output_dir}"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Cell Flow 的异常体系与对应退出码。"""


class CellFlowError(Exception):
    """所有 Cell Flow 受控错误的基类，携带确定退出码。"""

    exit_code = 1


class CellFlowInputError(CellFlowError):
    """输入矩阵不合法（空路径、不可读、表头缺失、ID 重复、空矩阵、非法计数）。"""

    exit_code = 2


class CellFlowConfigError(CellFlowError):
    """命令行参数冲突或取值非法。"""

    exit_code = 3


class CellFlowDataError(CellFlowError):
    """数据无法支撑分析（质控后细胞不足、无可用基因、PCA/聚类无法成立）。"""

    exit_code = 4


class OutputPathError(CellFlowError):
    """结果目录已存在且非空。"""

    exit_code = 5

"""输入矩阵读取与严格校验。

输入为制表符分隔矩阵：首列是唯一基因 ID，其余列名是唯一细胞 ID，
取值为非负整数 UMI 计数。文件承载方式有两种：UTF-8 制表符纯文本，
或其单成员 gzip 压缩文件（按 gzip 魔数自动识别，与文件名无关）。
任何不合法情形（含 gzip 头、CRC、长度校验失败、截断、多成员或
尾随数据）都抛出 :class:`cell_flow.errors.CellFlowInputError`。
"""

import hashlib
import os
import re
import zlib
from dataclasses import dataclass, field
from typing import List

from .errors import CellFlowInputError

_INTEGER_RE = re.compile(r"^(0|[1-9][0-9]*)$")

GZIP_MAGIC = b"\x1f\x8b"


@dataclass(frozen=True)
class InputFile:
    """一个输入文件的来源记录：文件名与原始字节的 SHA-256。"""

    name: str
    sha256: str


@dataclass(frozen=True)
class ExpressionMatrix:
    """原始计数矩阵（行＝基因，列＝细胞）。

    ``input_format`` 为 ``"tsv"`` 时沿用 ``path``/``sha256`` 单一文件记录
    （gzip 载体的 SHA-256 按压缩字节计算）；为 ``"mtx"`` 时 ``files`` 依次
    记录 matrix、barcodes、features 的实际文件名（含 ``.gz`` 后缀时亦然）
    与各自原始字节的 SHA-256。
    """

    gene_ids: List[str]
    cell_ids: List[str]
    counts: List[List[int]]  # counts[gene_index][cell_index]
    sha256: str
    path: str
    total_counts: int
    input_format: str = "tsv"
    files: List[InputFile] = field(default_factory=list)

    @property
    def n_genes(self) -> int:
        return len(self.gene_ids)

    @property
    def n_cells(self) -> int:
        return len(self.cell_ids)


def _fail(message: str) -> None:
    raise CellFlowInputError(message)


def gunzip_single(raw: bytes, path: str) -> bytes:
    """严格解压单成员 gzip 字节流。

    zlib 在 gzip 模式下对两类损坏静默：流尾截断（不返回错误，仅令
    ``eof`` 为假）与流后多余字节（放入 ``unused_data``）；而 CRC32 与
    ISIZE 不符会直接抛错。这里补齐前两项检查，并显式拒绝多成员
    （``unused_data`` 以 gzip 魔数开头即第二个成员）和任何尾随数据，
    确保流能被无损、无歧义地还原。
    """
    if len(raw) < 2 or raw[:2] != GZIP_MAGIC:
        _fail(f"gzip 头不合法：{path}（缺少魔数 {GZIP_MAGIC!r}）")
    decompressor = zlib.decompressobj(16 + zlib.MAX_WBITS)
    try:
        payload = decompressor.decompress(raw)
        payload += decompressor.flush()
    except zlib.error as exc:
        # 涵盖错误的压缩方法/标志、损坏的 deflate 数据、CRC32 与长度不符等
        _fail(f"gzip 数据无法无损还原：{path}（{exc}）")
    if not decompressor.eof:
        _fail(f"gzip 数据被截断或缺少完整尾部：{path}")
    if decompressor.unused_data:
        if decompressor.unused_data[:2] == GZIP_MAGIC:
            _fail(f"gzip 包含多个成员，仅允许单成员：{path}")
        _fail(f"gzip 流后存在尾随数据，仅允许单成员：{path}")
    return payload


def _parse_count(raw: str, gene_id: str, cell_id: str, row_no: int) -> int:
    if not _INTEGER_RE.match(raw):
        _fail(
            f"计数非法（第 {row_no} 行基因 {gene_id!r}、细胞 {cell_id!r}）："
            f"{raw!r} 不是非负整数"
        )
    return int(raw)


def read_matrix(path: str) -> ExpressionMatrix:
    if path is None or path == "":
        _fail("输入路径为空")
    if not os.path.exists(path):
        _fail(f"输入文件不存在：{path}")
    if not os.path.isfile(path):
        _fail(f"输入路径不是普通文件：{path}")
    if not os.access(path, os.R_OK):
        _fail(f"输入文件不可读：{path}")

    # SHA-256 始终按磁盘上的实际原始字节计算（gzip 即压缩字节），
    # 解析则基于解压后的文本；两者承载方式不同时矩阵内容一致。
    try:
        with open(path, "rb") as handle:
            raw_bytes = handle.read()
    except OSError as exc:
        _fail(f"输入文件不可读：{path}（{exc}）")

    digest = hashlib.sha256(raw_bytes).hexdigest()
    if raw_bytes[:2] == GZIP_MAGIC:
        text_bytes = gunzip_single(raw_bytes, path)
    else:
        text_bytes = raw_bytes
    try:
        text = text_bytes.decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"输入文件不是合法的 UTF-8 文本：{path}")

    # splitlines 同时兼容 \n 与 \r\n，且不会因末尾换行产生空行
    lines = text.splitlines()
    if not lines:
        _fail("表头缺失：文件为空")

    header = lines[0].split("\t")
    if len(header) < 2:
        _fail("表头缺失：至少需要基因 ID 列与一个细胞 ID 列")
    cell_ids = header[1:]
    if any(cell == "" for cell in cell_ids):
        _fail("表头存在空细胞 ID")
    if len(set(cell_ids)) != len(cell_ids):
        dup = _first_duplicate(cell_ids)
        _fail(f"细胞 ID 重复：{dup!r}")

    gene_ids: List[str] = []
    counts: List[List[int]] = []
    seen_genes = set()
    n_cells = len(cell_ids)

    for offset, line in enumerate(lines[1:], start=2):
        if line == "":
            _fail(f"第 {offset} 行为空，无法解析")
        fields = line.split("\t")
        if len(fields) != n_cells + 1:
            _fail(
                f"第 {offset} 行列数为 {len(fields) - 1}，"
                f"与表头细胞数 {n_cells} 不一致"
            )
        gene_id = fields[0]
        if gene_id == "":
            _fail(f"第 {offset} 行基因 ID 为空")
        if gene_id in seen_genes:
            _fail(f"基因 ID 重复：{gene_id!r}")
        seen_genes.add(gene_id)
        row = [
            _parse_count(fields[c + 1], gene_id, cell_ids[c], offset)
            for c in range(n_cells)
        ]
        gene_ids.append(gene_id)
        counts.append(row)

    if not gene_ids:
        _fail("空矩阵：没有任何基因数据行")

    total = 0
    for row in counts:
        total += sum(row)

    return ExpressionMatrix(
        gene_ids=gene_ids,
        cell_ids=cell_ids,
        counts=counts,
        sha256=digest,
        path=path,
        total_counts=total,
    )


def _first_duplicate(values: List[str]) -> str:
    seen = set()
    for value in values:
        if value in seen:
            return value
        seen.add(value)
    return values[0]

