        "--min-cells": "min_cells",
        "--mito-prefix": "mito_prefix",
        "--n-hvg": "n_hvg",
        "--n-pcs": "n_pcs",
        "--n-clusters": "n_clusters",
        "--seed": "seed",
    }
    options = {
        "input_format": "tsv",
        "min_genes": "200",
        "max_mito_fraction": "0.2",
        "min_cells": "3",
